fn fibonacci(n: usize) -> Vec<i32> {
    // We assume n >= 2 as per problem statement.
    let mut fibs = Vec::with_capacity(n);
    fibs.push(0);
    fibs.push(1);

    for i in 2..n {
        // Safe to add without overflow because F(n) < 2^31 for requested n
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}

